#[derive(Clone)]
pub struct Client {
    invalidated: std::sync::Arc<std::sync::atomic::AtomicBool>,
    #[cfg(unix)]
    remote: Option<std::sync::Arc<std::path::PathBuf>>,
    profile_auth: Option<signed::AuthConfig>,
    subscriptions: std::sync::Arc<
        tokio::sync::Mutex<
            std::collections::BTreeMap<String, std::sync::Arc<subscription::Subscription>>,
        >,
    >,
    receivers: std::sync::Arc<
        tokio::sync::Mutex<
            std::collections::BTreeMap<String, std::sync::Arc<tokio::sync::Mutex<Receiver>>>,
        >,
    >,
    reconnect: std::sync::Arc<tokio::sync::Mutex<Reconnect>>,
    http: reqwest::Client,
    signed: Option<std::sync::Arc<signed::SignedClient>>,
}
#[derive(Default)]
struct Receiver {
    stream: Option<Events>,
    after: u64,
    last: Option<Value>,
}
#[derive(Default)]
struct Reconnect {
    failures: u32,
    not_before: Option<tokio::time::Instant>,
}
pub struct Events {
    expires_at: Option<i64>,
    expiry: Option<tokio::task::JoinHandle<()>>,
    _permits: Option<(
        tokio::sync::OwnedSemaphorePermit,
        tokio::sync::OwnedSemaphorePermit,
    )>,
    observer: Option<(
        std::sync::Arc<std::sync::atomic::AtomicBool>,
        std::sync::Arc<tokio::sync::Notify>,
    )>,
    opened: std::time::Instant,
    response: reqwest::Response,
    buffer: Vec<u8>,
    handshake: Option<(String, Value, u8, Option<String>)>,
    verifier: Option<(std::sync::Arc<signed::SignedClient>, reqwest::Client)>,
}
impl Drop for Events {
    fn drop(&mut self) {
        if let Some(timer) = self.expiry.take() {
            timer.abort();
        }
        if self._permits.is_some() {
            metrics::STREAMS_ACTIVE.fetch_sub(1, std::sync::atomic::Ordering::Relaxed);
        }
        if let Some((active, changed)) = &self.observer {
            active.store(false, std::sync::atomic::Ordering::SeqCst);
            changed.notify_waiters();
        }
    }
}
impl Events {
    fn observe(
        &mut self,
        observer: Option<(
            std::sync::Arc<std::sync::atomic::AtomicBool>,
            std::sync::Arc<tokio::sync::Notify>,
        )>,
    ) -> Result<()> {
        self.observer = observer;
        if let Some(timer) = self.expiry.take() {
            timer.abort();
        }
        let ready = self.handshake.as_ref().is_none_or(|h| h.2 == 2);
        if ready && self.expires_at.is_none() {
            self.expires_at = Some(signed::now()? + 1800);
        }
        if let Some((active, changed)) = &self.observer {
            let remaining = self.expires_at.unwrap_or(0) - signed::now()?;
            active.store(ready && remaining > 0, std::sync::atomic::Ordering::SeqCst);
            changed.notify_waiters();
            if ready && remaining > 0 {
                let active = active.clone();
                let changed = changed.clone();
                self.expiry = Some(tokio::spawn(async move {
                    tokio::time::sleep(std::time::Duration::from_secs(remaining as u64)).await;
                    active.store(false, std::sync::atomic::Ordering::SeqCst);
                    changed.notify_waiters();
                }));
            }
        }
        Ok(())
    }
    fn stable(&self) -> bool {
        self.opened.elapsed() >= std::time::Duration::from_secs(60)
    }

    async fn next(&mut self) -> Result<Option<Value>> {
        timing::measure("sse.wait_and_verify", "subscribe", self.next_inner()).await
    }
    async fn next_inner(&mut self) -> Result<Option<Value>> {
        loop {
            if self
                .expires_at
                .is_some_and(|deadline| signed::now().is_ok_and(|now| now >= deadline))
            {
                return Err(signed::StreamFailure {
                    status: 503,
                    retry_after: 1,
                    code: Some("stream_renewal_required".into()),
                }
                .into());
            }
            let boundary = self
                .buffer
                .windows(2)
                .position(|w| w == b"\n\n")
                .map(|end| (end, 2))
                .or_else(|| {
                    self.buffer
                        .windows(4)
                        .position(|w| w == b"\r\n\r\n")
                        .map(|end| (end, 4))
                });
            if let Some((end, separator)) = boundary {
                let frame: Vec<u8> = self.buffer.drain(..end + separator).collect();
                let text = std::str::from_utf8(&frame).context("invalid event UTF-8")?;
                let data = text
                    .lines()
                    .filter_map(|line| line.strip_prefix("data:").map(str::trim_start))
                    .collect::<Vec<_>>()
                    .join("\n");
                if !data.is_empty() {
                    let value: Value = serde_json::from_str(&data)?;
                    if let Some((nonce, args, phase, connection)) = &mut self.handshake {
                        let event = text
                            .lines()
                            .find_map(|l| l.strip_prefix("event:").map(str::trim))
                            .unwrap_or("");
                        match event {
                            "challenge" if *phase == 0 => {
                                let (client, http) =
                                    self.verifier.as_ref().context("missing stream verifier")?;
                                client
                                    .authenticate_stream(http, &value, nonce, args)
                                    .await?;
                                *connection = value["connection_id"].as_str().map(str::to_owned);
                                *phase = 1;
                                continue;
                            }
                            "ready" if *phase == 1 => {
                                anyhow::ensure!(
                                    value["connection_id"].as_str() == connection.as_deref(),
                                    "stream connection mismatch"
                                );
                                *phase = 2;
                                let expires = value["expires_at"]
                                    .as_i64()
                                    .context("missing stream expiry")?;
                                anyhow::ensure!(
                                    expires > signed::now()? && expires <= signed::now()? + 1830,
                                    "invalid stream expiry"
                                );
                                self.expires_at = Some(expires);
                                self.observe(self.observer.clone())?;
                                continue;
                            }
                            "messages" if *phase == 2 => {}
                            "error" => {
                                if let Some((client, _)) = &self.verifier {
                                    let origin = url::Url::parse(&client.project_url)?
                                        .origin()
                                        .ascii_serialization();
                                    quota::note(
                                        &origin,
                                        value["status"].as_u64().unwrap_or(503) as u16,
                                        value["code"].as_str(),
                                        value["retry_after"].as_u64().unwrap_or(60),
                                    )?;
                                }
                                return Err(signed::StreamFailure {
                                    code: value["code"].as_str().map(str::to_owned),
                                    status: value["status"].as_u64().unwrap_or(503) as u16,
                                    retry_after: value["retry_after"].as_u64().unwrap_or(0),
                                }
                                .into());
                            }
                            _ => bail!("unexpected stream event during authentication"),
                        }
                    }

                    anyhow::ensure!(
                        self.expires_at
                            .is_none_or(|deadline| signed::now().is_ok_and(|now| now < deadline)),
                        "stream access expired"
                    );
                    let value = if let Some((client, http)) = &self.verifier {
                        client.verify_history(http, value).await?
                    } else {
                        value
                    };
                    return Ok(Some(value));
                }
                continue;
            }
            match tokio::time::timeout(std::time::Duration::from_secs(45), self.response.chunk())
                .await
                .context("event heartbeat timed out")??
            {
                Some(chunk) => {
                    self.buffer.extend_from_slice(&chunk);
                    let limit = if self.verifier.is_some() {
                        8 * 1024 * 1024
                    } else {
                        256 * 1024 * 1024
                    };
                    if self.buffer.len() > limit {
                        bail!("event exceeds the client size limit");
                    }
                }
                None => return Ok(None),
            }
        }
    }
}
fn transient(error: &anyhow::Error) -> bool {
    if let Some(e) = error.downcast_ref::<signed::StreamFailure>() {
        return e.status == 429 || e.status >= 500;
    }
    error.downcast_ref::<reqwest::Error>().is_some_and(|e| {
        if let Some(status) = e.status() {
            return status.is_server_error() || status.as_u16() == 429;
        }
        e.is_connect() || e.is_request() || e.is_timeout() || e.is_body()
    })
}
impl Client {
    fn check_valid(&self) -> Result<()> {
        anyhow::ensure!(
            !self.invalidated.load(std::sync::atomic::Ordering::SeqCst),
            "profile changed; reconnect with the current configuration"
        );
        Ok(())
    }

    fn auth(&self) -> Result<&signed::AuthConfig> {
        self.signed
            .as_ref()
            .map(|c| &c.auth)
            .or(self.profile_auth.as_ref())
            .context("signed profile required")
    }

    async fn note_stream_error(&self, error: &anyhow::Error) {
        if let Some(e) = error.downcast_ref::<signed::StreamFailure>() {
            let until = tokio::time::Instant::now()
                + std::time::Duration::from_secs(e.retry_after.min(86400));
            let mut state = self.reconnect.lock().await;
            state.not_before = Some(state.not_before.map_or(until, |old| old.max(until)));
        }
    }
    async fn reconnect_wait(&self) {
        metrics::RECONNECTS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let until = {
            let mut state = self.reconnect.lock().await;
            let seconds = (1u64 << state.failures.min(6)).min(60);
            state.failures = state.failures.saturating_add(1);
            let mut random = [0u8; 2];
            let _ = getrandom::getrandom(&mut random);
            let jitter = u16::from_le_bytes(random) as u64 % (seconds * 250 + 1);
            let until = tokio::time::Instant::now()
                + std::time::Duration::from_millis(seconds * 1000 + jitter);
            let until = state.not_before.map_or(until, |old| old.max(until));
            state.not_before = Some(until);
            until
        };
        tokio::time::sleep_until(until).await;
    }
    async fn stable_connection(&self, stable: bool) {
        if stable {
            self.reconnect.lock().await.failures = 0;
        }
    }

    // A dedicated client has no whole-response timeout: SSE is intentionally long-lived.
    async fn events(&self, args: &Value) -> Result<Option<Events>> {
        let until = self.reconnect.lock().await.not_before;
        if let Some(until) = until {
            tokio::time::sleep_until(until).await;
        }

        let http = reqwest::Client::builder()
            .connect_timeout(std::time::Duration::from_secs(10))
            .redirect(reqwest::redirect::Policy::none())
            .build()?;
        let signed = self
            .signed
            .as_ref()
            .context("signed authentication required")?;
        let permits = limits::stream(&signed.stream_scope())?;
        metrics::STREAM_STARTS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let capable = signed.stream_capable(&self.http).await?;
        let (response, handshake) = if capable {
            let (response, nonce) = tokio::time::timeout(
                std::time::Duration::from_secs(15),
                signed.open_stream(&http),
            )
            .await
            .context("event connection timed out")??;
            (response, Some((nonce, args.clone(), 0, None)))
        } else {
            (
                tokio::time::timeout(
                    std::time::Duration::from_secs(15),
                    signed.events(&http, args),
                )
                .await
                .context("event connection timed out")??,
                None,
            )
        };
        metrics::STREAMS_ACTIVE.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        Ok(Some(Events {
            expires_at: None,
            expiry: None,
            _permits: Some(permits),
            observer: None,
            opened: std::time::Instant::now(),
            response,
            handshake,
            buffer: Vec::new(),
            verifier: Some((signed.clone(), self.http.clone())),
        }))
    }

    async fn receive(&self, args: Value) -> Result<Value> {
        self.check_valid()?;
        #[cfg(unix)]
        if let Some(profile) = &self.remote {
            return broker::call(profile, "receive", args).await;
        }
        subscription::receive(self, args).await
    }
    #[cfg(test)]
    async fn receive_direct(&self, args: Value) -> Result<Value> {
        self.receive_observed(args, None).await
    }
    async fn receive_observed(
        &self,
        mut args: Value,
        observer: Option<(
            std::sync::Arc<std::sync::atomic::AtomicBool>,
            std::sync::Arc<tokio::sync::Notify>,
        )>,
    ) -> Result<Value> {
        let seconds = args["timeout_seconds"]
            .as_u64()
            .unwrap_or(300)
            .clamp(1, 300);
        let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(seconds);
        args.as_object_mut()
            .context("invalid receive arguments")?
            .remove("timeout_seconds");
        let requested = args["after"].as_u64().unwrap_or(0);
        let mut key_args = args.clone();
        key_args.as_object_mut().unwrap().remove("after");
        let key = serde_json::to_string(&key_args)?;
        let slot = {
            let mut slots = self.receivers.lock().await;
            if !slots.contains_key(&key) && slots.len() >= 4 {
                bail!("too many receive subscriptions");
            }
            slots.entry(key).or_default().clone()
        };
        let mut receiver = tokio::time::timeout_at(deadline, slot.lock())
            .await
            .context("receive already waiting")?;
        if let Some(stream) = receiver.stream.as_mut() {
            stream.observe(observer.clone())?;
        }
        if requested < receiver.after {
            if let Some(last) = &receiver.last {
                let first = last["messages"]
                    .as_array()
                    .and_then(|m| m.first())
                    .and_then(|m| m["id"].as_u64())
                    .unwrap_or(u64::MAX);
                if requested >= first.saturating_sub(1) {
                    let mut page = last.clone();
                    page["messages"]
                        .as_array_mut()
                        .unwrap()
                        .retain(|m| m["id"].as_u64().is_some_and(|id| id > requested));
                    return Ok(page);
                }
            }
            return self.call("history", args).await;
        }
        if requested > receiver.after {
            receiver.stream = None;
            receiver.after = requested;
        }
        loop {
            if receiver.stream.is_none() {
                args["after"] = json!(receiver.after);
                match tokio::time::timeout_at(deadline, self.events(&args)).await {
                    Ok(Ok(mut stream)) => {
                        if let Some(stream) = stream.as_mut() {
                            stream.observe(observer.clone())?;
                        }
                        receiver.stream = stream;
                    }
                    Ok(Err(e))
                        if transient(&e) || e.to_string() == "event connection timed out" =>
                    {
                        self.note_stream_error(&e).await;
                        let _ = tokio::time::timeout_at(deadline, self.reconnect_wait()).await;
                    }
                    Ok(Err(e)) => return Err(e),
                    Err(_) => break,
                }
            }
            if let Some(stream) = receiver.stream.as_mut() {
                match tokio::time::timeout_at(deadline, stream.next()).await {
                    Ok(Ok(Some(page))) => {
                        receiver.after = page["messages"]
                            .as_array()
                            .into_iter()
                            .flatten()
                            .filter_map(|m| m["id"].as_u64())
                            .max()
                            .unwrap_or(receiver.after);
                        receiver.last = Some(page.clone());
                        return Ok(page);
                    }
                    Err(_) => {
                        if stream.handshake.as_ref().is_some_and(|h| h.2 < 2) {
                            receiver.stream = None;
                        }
                        break;
                    }
                    Ok(Err(e))
                        if !transient(&e) && e.to_string() != "event heartbeat timed out" =>
                    {
                        receiver.stream = None;
                        return Err(e);
                    }
                    other => {
                        if let Ok(Err(e)) = &other {
                            self.note_stream_error(e).await;
                        }
                        self.stable_connection(stream.stable()).await;
                        receiver.stream = None;
                        let _ = tokio::time::timeout_at(deadline, self.reconnect_wait()).await;
                    }
                }
            }
            if tokio::time::Instant::now() >= deadline {
                break;
            }
        }
        if receiver
            .stream
            .as_ref()
            .is_some_and(|stream| stream.handshake.as_ref().is_none_or(|h| h.2 == 2))
        {
            return Ok(json!({"messages":[],"has_more":false}));
        }
        Err(signed::StreamFailure {
            status: 503,
            retry_after: 1,
            code: Some("subscription_reconnecting".into()),
        }
        .into())
    }
    async fn retry(&self, operation_id: &str) -> Result<Value> {
        self.check_valid()?;
        #[cfg(unix)]
        if let Some(profile) = &self.remote {
            return broker::call(profile, "retry", json!({"operation_id":operation_id})).await;
        }
        self.signed
            .as_ref()
            .context("retry requires signed authentication")?
            .retry(&self.http, operation_id)
            .await
    }
    async fn call_id(&self, operation: &str, args: Value, id: &str) -> Result<Value> {
        self.check_valid()?;
        self.signed
            .as_ref()
            .context("signed authentication required")?
            .call_id(&self.http, operation, args, id)
            .await
    }
    async fn call(&self, operation: &str, args: Value) -> Result<Value> {
        self.check_valid()?;
        #[cfg(unix)]
        if let Some(profile) = &self.remote {
            return broker::call(profile, operation, args).await;
        }
        self.signed
            .as_ref()
            .context("signed authentication required")?
            .call(&self.http, operation, args)
            .await
    }
}

fn client_from_config(
    config: &Config,
    server: Option<String>,
    session: Option<String>,
) -> Result<Client> {
    anyhow::ensure!(
        config.auth.is_some() && config.project_url.is_some(),
        "project_url and signed auth are required"
    );
    let signed = match (&config.auth, &config.project_url) {
        (Some(auth), Some(url)) => {
            if config.session.is_some()
                || session.is_some()
                || server.is_some()
                || config.server.is_some()
            {
                bail!(
                    "signed authentication cannot be combined with server/session overrides; use project_url"
                );
            }
            Some(std::sync::Arc::new(signed::SignedClient::new(
                url,
                auth.clone(),
                config.compat.clone(),
            )?))
        }
        (None, None) => None,
        _ => bail!("project_url and auth must be configured together"),
    };
    let mut http = reqwest::Client::builder().timeout(std::time::Duration::from_secs(30));
    if signed.is_some() {
        http = http.redirect(reqwest::redirect::Policy::none());
    }
    Ok(Client {
        receivers: Default::default(),
        subscriptions: Default::default(),
        #[cfg(unix)]
        remote: None,
        profile_auth: None,
        invalidated: Default::default(),
        reconnect: Default::default(),
        http: http.build()?,
        signed,
    })
}

#[cfg(test)]
mod cli_tests {
    use super::*;
    #[test]
    fn invitation_file_is_an_alternative_to_the_legacy_join_arguments() {
        let common = [
            "cc-sakura",
            "auth",
            "join",
            "--private-key-file",
            "/tmp/agent.key",
            "--out",
            "/tmp/room.toml",
        ];
        let parse =
            |extra: &[&str]| Cli::try_parse_from(common.into_iter().chain(extra.iter().copied()));
        assert!(parse(&["--invitation-file", "/tmp/invite.json"]).is_ok());
        assert!(
            parse(&[
                "--project-url",
                "https://example.com/owner/room",
                "--token-file",
                "/tmp/token.txt"
            ])
            .is_ok()
        );
        assert!(parse(&[]).is_err());
        assert!(parse(&["--project-url", "https://example.com/owner/room"]).is_err());
        assert!(
            parse(&[
                "--invitation-file",
                "/tmp/invite.json",
                "--token-file",
                "/tmp/token.txt"
            ])
            .is_err()
        );
        assert!(
            parse(&[
                "--invitation-file",
                "/tmp/invite.json",
                "--project-url",
                "https://example.com/owner/room"
            ])
            .is_err()
        );
    }
}

#[cfg(test)]
mod reconnect_tests {
    use super::*;
    #[tokio::test]
    async fn retry_after_survives_a_cancelled_wait_and_client_clone() {
        let client = Client {
            http: reqwest::Client::new(),
            signed: None,
            reconnect: Default::default(),
            receivers: Default::default(),
            subscriptions: Default::default(),
            #[cfg(unix)]
            remote: None,
            profile_auth: None,
            invalidated: Default::default(),
        };
        client
            .note_stream_error(
                &signed::StreamFailure {
                    code: None,
                    status: 429,
                    retry_after: 120,
                }
                .into(),
            )
            .await;
        let until = client.reconnect.lock().await.not_before.unwrap();
        let clone = client.clone();
        assert!(
            tokio::time::timeout(std::time::Duration::from_millis(1), clone.reconnect_wait())
                .await
                .is_err()
        );
        assert!(client.reconnect.lock().await.not_before.unwrap() >= until);
        assert!(until > tokio::time::Instant::now() + std::time::Duration::from_secs(119));
        assert!(transient(
            &signed::StreamFailure {
                code: None,
                status: 503,
                retry_after: 0
            }
            .into()
        ));
        assert!(!transient(
            &signed::StreamFailure {
                code: None,
                status: 403,
                retry_after: 0
            }
            .into()
        ));
    }
}

#[cfg(test)]
mod stream_receiver_tests {
    use super::*;
    async fn response(text: &'static str) -> (reqwest::Response, tokio::task::JoinHandle<()>) {
        use axum::{Router, routing::get};
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap();
        let app = Router::new().route("/events", get(move || async move { text }));
        let task = tokio::spawn(async move {
            axum::serve(listener, app).await.unwrap();
        });
        let response = reqwest::get(format!("http://{address}/events"))
            .await
            .unwrap();
        (response, task)
    }
    #[tokio::test]
    async fn receive_reuses_stream_and_replays_cached_page_by_cursor() {
        let (response,task)=response("event: messages\ndata: {\"messages\":[{\"id\":1}]}\n\nevent: messages\ndata: {\"messages\":[{\"id\":2}]}\n\n").await;
        let stream = Events {
            expires_at: None,
            expiry: None,
            _permits: None,
            observer: None,
            response,
            opened: std::time::Instant::now(),
            buffer: vec![],
            handshake: None,
            verifier: None,
        };
        let client = Client {
            http: reqwest::Client::new(),
            signed: None,
            reconnect: Default::default(),
            receivers: Default::default(),
            subscriptions: Default::default(),
            #[cfg(unix)]
            remote: None,
            profile_auth: None,
            invalidated: Default::default(),
        };
        let args = json!({"after":0,"timeout_seconds":2});
        client.receivers.lock().await.insert(
            "{}".into(),
            std::sync::Arc::new(tokio::sync::Mutex::new(Receiver {
                stream: Some(stream),
                after: 0,
                last: None,
            })),
        );
        assert_eq!(
            client.receive_direct(args.clone()).await.unwrap()["messages"][0]["id"],
            1
        );
        assert_eq!(
            client.receive_direct(args).await.unwrap()["messages"][0]["id"],
            1
        );
        assert_eq!(
            client
                .receive_direct(json!({"after":1,"timeout_seconds":2}))
                .await
                .unwrap()["messages"][0]["id"],
            2
        );
        assert_eq!(client.receivers.lock().await.len(), 1);
        task.abort();
    }
    #[tokio::test]
    async fn observer_is_invalidated_at_expiry_and_on_drop() -> Result<()> {
        let (response, server) = response("").await;
        let active = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let changed = std::sync::Arc::new(tokio::sync::Notify::new());
        let mut events = Events {
            expires_at: Some(signed::now()? + 1),
            expiry: None,
            _permits: None,
            observer: None,
            opened: std::time::Instant::now(),
            response,
            buffer: vec![],
            handshake: None,
            verifier: None,
        };
        events.observe(Some((active.clone(), changed.clone())))?;
        assert!(active.load(std::sync::atomic::Ordering::SeqCst));
        tokio::time::sleep(std::time::Duration::from_millis(1100)).await;
        assert!(!active.load(std::sync::atomic::Ordering::SeqCst));
        assert!(
            events
                .next()
                .await
                .unwrap_err()
                .downcast_ref::<signed::StreamFailure>()
                .is_some()
        );
        events.expires_at = Some(signed::now()? + 30);
        events.observe(Some((active.clone(), changed)))?;
        drop(events);
        assert!(!active.load(std::sync::atomic::Ordering::SeqCst));
        server.abort();
        Ok(())
    }
    #[tokio::test]
    async fn rejects_messages_before_authentication_and_classifies_sse_errors() {
        let (response, task) = response("event: messages\ndata: {\"messages\":[]}\n\n").await;
        let mut events = Events {
            expires_at: None,
            expiry: None,
            _permits: None,
            observer: None,
            response,
            opened: std::time::Instant::now(),
            buffer: vec![],
            handshake: Some(("nonce".into(), json!({}), 0, None)),
            verifier: None,
        };
        assert!(
            events
                .next()
                .await
                .unwrap_err()
                .to_string()
                .contains("unexpected stream event")
        );
        task.abort();
    }
}
